{
  "category_edits": [
    {
      "category": "sequence_interest",
      "rationale": "Reduce observed-history length from 128 to 32 across all four categories to test whether excluding older interactions reduces stale-interest interference. Existing checkpoint metadata saves MAXLEN and drives inference truncation. Preserve final-real-position readout, embeddings, GRU topology, scoring, loss and optimizer.",
      "edits": [
        {
          "find": "MAXLEN        = int(os.environ.get(\"GRU4REC_MAXLEN\", \"128\"))",
          "replace": "MAXLEN        = int(os.environ.get(\"GRU4REC_MAXLEN\", \"32\"))"
        },
        {
          "find": "    maxlen = int(meta.get(\"maxlen\", 128))",
          "replace": "    maxlen = int(meta.get(\"maxlen\", 32))"
        }
      ]
    }
  ],
  "change_summary": "Use a 32-item observed-history window for training and inference, with matching predictor fallback and existing checkpoint metadata."
}
